// === Tab: mySketch ===
var particles = [];
var incAngle = 0.0;
var incAngle2 = 0.0;

var cx;
var cy;
var r = 3000;
var a = 0.0025;
var c;


function setup() {
    createCanvas(windowWidth, windowHeight);
    colorMode(HSB, 100);
    c = floor(random(0, 100));
		cx = windowWidth/2;
		cy = windowHeight/2;
    for(var i = 0; i < 1000; i++) {
        var t = radians(i*5);
        var x = cx + a * t * r * cos(t);
        var y = cy + a * t * r * sin(t);
        c++;
        if(c == 100) c = 0;
        particles.push(new Particle(x, y, c));
    }

}

function Particle(x, y, c) {
    this.pos = createVector(random(width), random(height));
    this.target = createVector(x, y);
    this.vel = p5.Vector.random2D();
    this.acc = createVector();
    this.r = 8;
    this.maxSpeed = 8;
    this.maxForce = 1;
    this.c = c;
}

Particle.prototype.update = function() {
    this.pos.add(this.vel);
    this.vel.add(this.acc);
    this.acc.mult(0);
}

Particle.prototype.behaviors = function() {
    var arrive = this.arrive(this.target);
    var mouse = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    var flee = this.flee(mouse);

    arrive.mult(1);
    flee.mult(10);

    this.applyForce(arrive);
    this.applyForce(flee);

}

Particle.prototype.applyForce = function(f) {
    this.acc.add(f);
}

Particle.prototype.show = function() {
    stroke(this.c, 80, 100);
    strokeWeight(20);
    point(this.pos.x, this.pos.y);
}

Particle.prototype.arrive = function(target) {
    var desired = p5.Vector.sub(target, this.pos);
    var d = desired.mag();
    var speed = this.maxSpeed;
    if(d < 100) {
        speed = map(d, 0, 100, 0, this.maxSpeed);
    }
    desired.setMag(speed);
    var steer = p5.Vector.sub(desired, this.vel);
    steer.limit(this.maxForce);
    return steer;
}

Particle.prototype.flee = function(target) {
    var desired = p5.Vector.sub(target, this.pos);
    var d = desired.mag();
    if(d < 50) {
        desired.setMag(this.maxSpeed);
        desired.mult(-1);
        var steer = p5.Vector.sub(desired, this.vel);
        steer.limit(this.maxForce);
        return steer;
    }
    else return createVector(0,0);
}

function draw() {
    background(0);
    for(var j = 0; j < particles.length; j++) {
        particles[j].show();
        particles[j].update();
        particles[j].behaviors();
    }

    if(keyIsDown(32)) {
        background(0);
        particles = [];
        setup();
    }

}

